var tiles = Array.prototype.slice.call(root.querySelectorAll('.mk12-feature-grid-tile'));
var note = root.querySelector('.mk12-feature-grid-note');
if(!tiles.length) return;
function select(idx, moveFocus){
  tiles.forEach(function(t, j){ t.setAttribute('aria-pressed', j === idx ? 'true' : 'false'); });
  var copy = tiles[idx].getAttribute('data-mk12-copy');
  if(note && copy){
    note.textContent = copy;
    note.removeAttribute('data-mk12-swap');
    void note.offsetWidth;
    note.setAttribute('data-mk12-swap', '1');
  }
  if(moveFocus) tiles[idx].focus();
}
tiles.forEach(function(tile, i){
  tile.addEventListener('click', function(){ select(i, false); });
  tile.addEventListener('keydown', function(e){
    var next = null;
    if(e.key === 'ArrowRight' || e.key === 'ArrowDown') next = (i + 1) % tiles.length;
    else if(e.key === 'ArrowLeft' || e.key === 'ArrowUp') next = (i - 1 + tiles.length) % tiles.length;
    else if(e.key === 'Home') next = 0;
    else if(e.key === 'End') next = tiles.length - 1;
    if(next !== null){ e.preventDefault(); select(next, true); }
  });
});

