var input = root.querySelector('.mk12-cta-band-input');
var msg = root.querySelector('.mk12-cta-band-msg');
var btn = root.querySelector('.mk12-cta-band-btn');
var timer = null;
function state(s){
  root.removeAttribute('data-mk12-state');
  void root.offsetWidth;
  root.setAttribute('data-mk12-state', s);
}
root.setAttribute('data-mk12-state', 'idle');
root.addEventListener('submit', function(e){
  e.preventDefault();
  if(!input) return;
  if(root.getAttribute('data-mk12-state') === 'loading') return;
  var value = (input.value || '').trim();
  var ok = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(value);
  if(!ok){
    state('error');
    input.setAttribute('aria-invalid', 'true');
    if(msg) msg.textContent = 'That email does not look right — try again.';
    input.focus();
    return;
  }
  input.removeAttribute('aria-invalid');
  state('loading');
  if(btn){ btn.disabled = true; btn.setAttribute('aria-busy', 'true'); }
  if(msg) msg.textContent = 'Signing you up…';
  clearTimeout(timer);
  timer = setTimeout(function(){
    state('done');
    if(btn){ btn.removeAttribute('aria-busy'); }
    if(msg) msg.textContent = 'You are in. First issue lands Thursday, 9am.';
    input.readOnly = true;
  }, 1100);
});
