    if(root.getAttribute('data-mk12-state') === 'error'){
      root.setAttribute('data-mk12-state', 'idle');
      input.removeAttribute('aria-invalid');
      if(msg) msg.textContent = 'No spam. Unsubscribe in one click.';
    }
  });
}

